blocks.javascript:
// 동적 타입 JavaScript
let x = 5;
x = "hello";  // 가능 — 런타임에 타입 변경

// 약타입: 암묵적 변환
console.log("1" + 1);  // "11" (문자열 연결)
console.log("5" - 1);  // 4   (숫자로 변환)

